import heapq
from itertools import combinations


def _round(n, mode):
    if mode == "half_up":
        return (n + 5000) // 10000
    return n // 10000


def _ledger(data, sequence_first, discounted):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            rank = (sequence, event.get("revision", 0), pos)
        else:
            rank = (event.get("revision", 0), pos)
        if event_id not in winners or rank > winners[event_id][0]:
            winners[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data.get("rounding", "floor")
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        tax_base = net if discounted else raw
        tax = _round(tax_base * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    options = [sorted(rows[name], reverse=True) + [-1] for name in names]

    for vector in product(*options):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        if any(name not in selected for name in roots):
            continue
        if any(version in blocked.get(name, []) or
               (name in pins and pins[name] != version)
               for name, version in selected.items()):
            continue

        constraints = {name: [] for name in selected}
        for name, bounds in roots.items():
            constraints[name].append(tuple(bounds))
        closure = set(roots)
        pending = list(roots)
        graph = {name: [] for name in selected}
        valid = True
        while pending and valid:
            name = pending.pop()
            if name not in selected:
                valid = False
                break
            row = rows[name][selected[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in selected:
                    valid = False
                    break
                constraints[other].append((dep["min"], dep["max"]))
                graph[name].append(other)
                if other not in closure:
                    closure.add(other)
                    pending.append(other)
        if not valid or closure != set(selected):
            continue
        if any(not low <= selected[name] <= high
               for name, limits in constraints.items()
               for low, high in limits):
            continue

        state = {}
        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not acyclic(other) for other in graph[name]):
                return False
            state[name] = 2
            return True

        if all(acyclic(name) for name in selected):
            return {"versions": selected}
    return {"error": "unsatisfiable"}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for chosen in combinations(jobs, k):
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= t < job["end"] for job in chosen) > 2
               for t in {job["start"] for job in chosen}):
            continue
        value = sum(job["value"] for job in chosen)
        id_list = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], left)]
            if left:
                choices.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
            next_node = edge["v"]
            next_mask = mask | bit.get(next_node, 0)
            for duration, next_left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, next_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_left))
    return {"arrival": None}


